head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF76220";
scwin.G_vertical = '\u000B';
scwin.G_formfeed = '\u000C';
scwin.editor = undefined;
scwin.upload = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd, pageContext.usrTpCd, status

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "if_usrTpCd", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_4", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_5", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_6", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "btn_update", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "btn_del", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider
    try {
        frame.Title = "관련법규변경";
        const status = (String(((dma_pageContext.get("status") ?? "")) == null ? '' : ((dma_pageContext.get("status") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("status") ?? "")) == null ? '' : ((dma_pageContext.get("status") ?? ""))));
        if ("update" === status) {
            let fn_reload = $c.win.getParent().fn_reload;
            fn_reload();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_reload — as-is 정의 없음(원본 JS 미제공 — 회신)
            await $c.win.alert("수정되었습니다.");
        } else {
            if ("register" === status) {
                fn_reload = $c.win.getParent().fn_reload;
                fn_reload();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_reload — as-is 정의 없음(원본 JS 미제공 — 회신)
                await $c.win.alert("등록되었습니다.");
            } else {
                if ("delete" === status) {
                    fn_reload = $c.win.getParent().fn_reload;
                    fn_reload();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_reload — as-is 정의 없음(원본 JS 미제공 — 회신)
                    await $c.win.alert("삭제되었습니다.");
                    $c.win.closePopup();
                }
            }
        }
        $c.util.getComponent('ipt_upSprtRoomNoTit').setValue("해당없음");
        $c.util.getComponent('ipt_upSprtRoomNoTit').setValue("" + dma_lawDetail.get("up_sprt_room_title") + "");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76220.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76220' }); }

try { scwin.upload =new Dext5Upload("dext5upload"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76220' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76220.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_66_onclick
 * @description 「상위법규검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_66_onclick = function(e){
    try {
        scwin.openUpLawPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76220.input_66_onclick' }); }
};

/**
 * @method
 * @name input_68_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_68_onclick = function(e){
    try {
        scwin.delValue()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76220.input_68_onclick' }); }
};

/**
 * @method
 * @name btn_update_onclick
 * @description 「변경」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_update_onclick = async function(e){
    try {
        await scwin.update()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76220.btn_update_onclick' }); }
};

/**
 * @method
 * @name btn_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_del_onclick = async function(e){
    try {
        await scwin.del()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76220.btn_del_onclick' }); }
};

/**
 * @method
 * @name btn_frame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_frame_onclick = function(e){
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76220.btn_frame_onclick' }); }
};

/**
 * @method
 * @name DEXT5UPLOAD_OnCreationComplete
 * @description DEXT5 UPLOAD On Creation Complete 처리
 * @returns {void}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnCreationComplete = function () {
    try {
        const attachStr = "" + dma_lawDetail.get("attachString") + "";
        if (attachStr.length > 0) {
            const temp1 = attachStr.split(scwin.G_vertical, 20);
            for (let i = 0; i < temp1.length - 1; i++) {
                const temp2 = temp1[i].split(scwin.G_formfeed, 20);
                DEXT5UPLOAD.AddUploadedFile(temp2[0], temp2[2], temp2[4], temp2[3], temp2[1], 'dext5upload');
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf76220.DEXT5UPLOAD_OnCreationComplete" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_dext5FileDown
 * @description dext5 File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_dext5FileDown = async function () {
    const sbmOptions = {
        id: "tx_dext5FileDown",
        method: "post",
        action: "/ods/dext5.do",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/dext5.do",
        ref: "dma_loadListReq",
        target: "dlt_chrgInstList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length === 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : $c.util.getComponent('ipt_sprtRoomtitle').focus());
        return;
    }
    const arrWhiteList = ["hwp", "hwpx", "xls", "xlsx", "docx", "doc", "ppt", "pptx", "pdf", "gif", "jpg", "jpeg", "bmp", "txt", "png", "zip"];
    const sFileNm = $('#dext5uploader_frame_dext5upload').contents().find('#file_list').find('.fname').find('span').text();
    const arrFileNm = sFileNm.split(".");
    const sExtFileNm = arrFileNm[arrFileNm.length-1].toLowerCase().trim();
    let cnt = 0;
    if (sExtFileNm != null && sExtFileNm.length > 0) {
        for (let j = 0; j < arrWhiteList.length; j++) {
            if (sExtFileNm === arrWhiteList[j]) {
                cnt++;
            }
        }
        if (cnt === 0) {
            await $c.win.alert("[" + sExtFileNm + "] 확장자는 등록할 수 없습니다.");
            return;
        }
    }
    if (await $c.win.confirm("저장하시겠습니까?")) {
        DEXT5UPLOAD.Transfer("dext5upload");
    }
};

/**
 * @method
 * @name DEXT5UPLOAD_OnTransfer_Complete
 * @description DEXT5 UPLOAD On Transfer Complete 처리
 * @param {String} dextId dextId
 * @returns {void}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnTransfer_Complete = function (dextId) {
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        let rtn = fn_newTextToString(textNew);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_newTextToString — 타 모듈 as-is 공통(stf/ods·ins/hindr) — 반입 범위 밖
        $('#ipt_attachFileInfo', $('#updateForm')).val(rtn);
    }
    const textDel = DEXT5UPLOAD.GetDeleteListForText("dext5upload");
    if (textDel != null) {
        rtn = fn_delTextToString(textDel);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_delTextToString — 타 모듈 as-is 공통(stf/ods·ins/hindr) — 반입 범위 밖
        $('#ipt_deleteFileInfo', $('#updateForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#updateForm')).val("/ui/jsp/JLDSTF76220.xml");
    $('#ipt_method', $('#updateForm')).val("updateSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    $('#updateForm').submit();
};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.del = async function () {
    if (await $c.win.confirm("삭제하시겠습니까?")) {
        $('#ipt_SCREN_ID', $('#updateForm')).val("/ui/jsp/JLDSTF76220.xml");
        $('#ipt_method', $('#updateForm')).val("delSprtRoom");
        $('#ipt_SCREN_PROCES_TP_CD', $('#updateForm')).val("04");
        $('#updateForm').submit();
    }
};

/**
 * @method
 * @name dext_editor_loaded_event
 * @description dext editor loaded event 처리
 * @param {*} editor editor
 * @returns {void}
 * @hidden N
 */
scwin.dext_editor_loaded_event = function (editor) {
    DEXT5.setHtmlValueEx($c.util.getComponent('ipt_webSprtRoomContn').getValue(), "dext5editor1");
};

/**
 * @method
 * @name DEXT5UPLOAD_BeforeFileDownload
 * @description DEXT5 UPLOAD Before File Download 처리
 * @param {String} uploadID uploadID
 * @param {*} strWebFile strWebFile
 * @param {*} strItemKey strItemKey
 * @param {*} strItemOrgName strItemOrgName
 * @param {*} strItemUrlOrPath strItemUrlOrPath
 * @param {*} strLargeFiles strLargeFiles
 * @param {*} strIsLastEvent strIsLastEvent
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.DEXT5UPLOAD_BeforeFileDownload = async function (uploadID, strWebFile, strItemKey, strItemOrgName, strItemUrlOrPath, strLargeFiles, strIsLastEvent) {
    let retVal = true;

    if (download_file_list === '') {
        download_file_list += strItemUrlOrPath;
        download_file_keys += strItemKey;
    } else {
        download_file_list += scwin.G_vertical + strItemUrlOrPath;
        download_file_keys += scwin.G_vertical + strItemKey;
    }
    if (strIsLastEvent === 1) {
        $c.util.getComponent('ipt_sprtRoomNoAttachSeq').setValue(download_file_keys);
        $c.util.getComponent('ipt_fileList').setValue(download_file_list);
        download_file_list = '';
        download_file_keys = '';
        await scwin.dext5FileDown();
        retVal = false;
    }
    return retVal;
};

/**
 * @method
 * @name fnCallDext5
 * @description fn Call Dext5 처리
 * @param {*} result result
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCallDext5 = async function (result) {
    if (result.fileStatus === 'ok') {
        DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "0";
        DEXT5UPLOAD.DownloadFile("dext5upload");
    } else {
        await $c.win.alert("파일다운로드 중 오류가 발생하였습니다. 관리자에게 문의하시기 바랍니다.");
    }
    DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "1";
};

/**
 * @method
 * @name openUpLawPop
 * @description open Up Law Pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.openUpLawPop = function () {
    const url = "/ods/sprtroom.do?method=readRelatedLawList&mode=popup&SCREN_ID=JLDODS76230.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "상위법규목록", width: "600px", height: "700px" }, {});
};

/**
 * @method
 * @name setData
 * @description set Data 처리
 * @param {*} tit tit
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.setData = function (tit, no) {
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue(tit);
    $c.util.getComponent('ipt_upSprtRoomNo').setValue(no);
};

/**
 * @method
 * @name delValue
 * @description del Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.delValue = function () {
    $c.util.getComponent('ipt_upSprtRoomNo').setValue('00000000000000');
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue('해당없음');
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name dext5FileDown_done
 * @description dext5 File Down done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dext5FileDown_done = async function (data) {
    await scwin.fnCallDext5(data);
};

/**
 * @method
 * @name dext5FileDown
 * @description dext5 File Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dext5FileDown = async function () {
    const r = await scwin.tx_dext5FileDown();
    try {
        scwin.dext5FileDown_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldstf76220.dext5FileDown' });
    }
    return r;
};
